import { describe, expect, it } from 'vitest';
import { PS_FAMILY } from '../src/fonts/ps-family';
import { familyOfPostScript, isKnownFamily, numberedFamily, spacelessFamily, typefaceFamily, type ProgramNames } from '../src/fonts/names';

/**
 * M4 Task 3: a font a PDF names only by its PostScript name gets its family through the PostScript-name table
 * (ps-family.ts, generated by harness/fonts/ps_family.py from its curated list and the font lock: public families only,
 * ruling M4-R8): subset tag off, the table, the style suffix, and a name without spaces only when the spaced name is a
 * family of the table.
 */

const of = (name: string) => familyOfPostScript(name);

describe('the PostScript-name table', () => {
  it('holds names only: each PostScript name to a family and a style, all non-empty strings', () => {
    for (const [ps, value] of Object.entries(PS_FAMILY)) {
      expect(ps).toMatch(/^[^\s/\\:*?"<>|]+$/);
      expect(value).toHaveLength(2);
      for (const v of value) expect(typeof v === 'string' && v.trim() !== '').toBe(true);
    }
    expect(Object.keys(PS_FAMILY)).toEqual([...Object.keys(PS_FAMILY)].sort());
  });

  it('knows the Windows, Office and lock families, by their own names', () => {
    for (const f of ['Malgun Gothic', 'Malgun Gothic Semilight', 'Gulim', 'Dotum', 'Batang', 'Gungsuh', 'Noto Sans KR', 'Arial', 'Calibri', 'Segoe UI', 'Times New Roman', 'Cambria', 'Consolas', 'Gothic A1', 'Pretendard', 'NanumGothic', 'HYGothic-Medium'])
      expect(isKnownFamily(f), f).toBe(true);
    expect(isKnownFamily('MalgunGothic')).toBe(false);
    expect(isKnownFamily('DeckbackSans')).toBe(false);
    // ruling M4-R8: a family of none of its sources is not in it, however common
    for (const f of ['Calibri Light', 'Segoe UI Semibold', 'Arial Black', 'GulimChe']) expect(isKnownFamily(f), f).toBe(false);
  });
});

describe('familyOfPostScript: table lookups', () => {
  it('a PostScript name of the table is its family and style', () => {
    expect(of('MalgunGothic')).toEqual({ family: 'Malgun Gothic', bold: false, italic: false });
    expect(of('MalgunGothicBold')).toEqual({ family: 'Malgun Gothic', bold: true, italic: false });
    expect(of('MalgunGothic-Semilight')).toEqual({ family: 'Malgun Gothic Semilight', bold: false, italic: false });
    expect(of('Arial-BoldItalicMT')).toEqual({ family: 'Arial', bold: true, italic: true });
    expect(of('TimesNewRomanPSMT')).toEqual({ family: 'Times New Roman', bold: false, italic: false });
    expect(of('NotoSansKR-Bold')).toEqual({ family: 'Noto Sans KR', bold: true, italic: false });
    expect(of('H2gtrM')).toEqual({ family: 'HYGothic-Medium', bold: false, italic: false });
    expect(of('GothicA1-Bold')).toEqual({ family: 'Gothic A1', bold: true, italic: false });
    expect(of('NanumGothicExtraBold')).toEqual({ family: 'NanumGothicExtraBold', bold: false, italic: false });
  });

  it('a subset tag comes off first', () => {
    expect(of('ABCDEF+MalgunGothicBold')).toEqual({ family: 'Malgun Gothic', bold: true, italic: false });
    expect(of('QWERTY+Pretendard-Light')).toEqual({ family: 'Pretendard Light', bold: false, italic: false });
  });
});

describe('familyOfPostScript: the style suffix', () => {
  it("Office's `,Bold` forms and the `-Style` forms", () => {
    expect(of('MalgunGothic,Bold')).toEqual({ family: 'Malgun Gothic', bold: true, italic: false });
    expect(of('Arial,BoldItalic')).toEqual({ family: 'Arial', bold: true, italic: true });
    expect(of('Arial,Italic')).toEqual({ family: 'Arial', bold: false, italic: true });
    expect(of('Gulim-Bold')).toEqual({ family: 'Gulim', bold: true, italic: false });
    expect(of('Consolas-Regular')).toEqual({ family: 'Consolas', bold: false, italic: false });
  });

  it('a weight is the family of that weight where the table has one, else the family, never bold', () => {
    expect(of('Pretendard,Light')).toEqual({ family: 'Pretendard Light', bold: false, italic: false });
    expect(of('MalgunGothic-SemiLight')).toEqual({ family: 'Malgun Gothic Semilight', bold: false, italic: false });
    expect(of('SegoeUI-SemiBold')).toEqual({ family: 'Segoe UI', bold: false, italic: false });
    expect(of('Calibri-Light')).toEqual({ family: 'Calibri', bold: false, italic: false });
    expect(of('NotoSansKR-Medium')).toEqual({ family: 'Noto Sans KR', bold: false, italic: false });
    expect(of('Pretendard-SemiBold')).toEqual({ family: 'Pretendard', bold: false, italic: false });
    expect(of('Pretendard-ExtraBold')).toEqual({ family: 'Pretendard', bold: false, italic: false });
    expect(of('MalgunGothic-SemilightItalic')).toEqual({ family: 'Malgun Gothic Semilight', bold: false, italic: true });
  });

  it('a style run on without a separator (`BoldItalic`)', () => {
    expect(of('DotumBold')).toEqual({ family: 'Dotum', bold: true, italic: false });
    expect(of('CambriaBoldItalic')).toEqual({ family: 'Cambria', bold: true, italic: true });
  });
});

describe('familyOfPostScript: a name without spaces', () => {
  it('is the spaced family only when the table has that family', () => {
    expect(of('TimesNewRoman')).toEqual({ family: 'Times New Roman', bold: false, italic: false });
    expect(of('TimesNewRoman,Bold')).toEqual({ family: 'Times New Roman', bold: true, italic: false });
    expect(of('NotoSansKR')).toEqual({ family: 'Noto Sans KR', bold: false, italic: false });
    expect(of('GothicA1')).toEqual({ family: 'Gothic A1', bold: false, italic: false });
    expect(of('ArialBlack')).toEqual({ family: 'Arial', bold: false, italic: false }); // Black: a weight of Arial here
    expect(of('SegoeUI')).toEqual({ family: 'Segoe UI', bold: false, italic: false });
  });

  it('a family with hyphens for its spaces, as PowerPoint names a variable font\'s instance (Noto-Sans-KR)', () => {
    expect(of('ABCDEF+Noto-Sans-KR')).toEqual({ family: 'Noto Sans KR', bold: false, italic: false });
    expect(of('Noto-Sans-KR-Bold')).toEqual({ family: 'Noto Sans KR', bold: true, italic: false });
    expect(of('Noto-Sans-JP')).toBeNull();
  });

  it('else nothing: a name the table does not know stays as the PDF has it', () => {
    for (const name of ['DeckbackSans-7Bold', 'FooBar', 'ABCDEF+FooBar-Bold', 'Noto Sans JP', '', 'Bold', ',Bold'])
      expect(of(name), name).toBeNull();
  });
});

describe('numberedFamily (M8 round 1a): a font PowerPoint embedded, its nameID 1 a number', () => {
  // the name records of b-d629f67e73, b-14cbf3aedb, b-6308ec98b7 and b-f639433217 (public fonts)
  const names = (o: Partial<ProgramNames>): ProgramNames => ({ family: '1', subfamily: 'Regular', full: null, postscript: null, typoFamily: null, typoSubfamily: null, ...o });

  it('a name that is no number is no numbered family', () => {
    expect(numberedFamily(names({ family: 'Catamaran' }))).toBeNull();
    expect(numberedFamily(names({ family: 'Catamaran 2' }))).toBeNull();
  });

  it('the typographic family (nameID 16), with a weight of nameID 17 that is not regular or bold as Windows names it', () => {
    expect(numberedFamily(names({ family: '11', full: '11', postscript: 'Catamaran-Light', typoFamily: 'Catamaran', typoSubfamily: 'Light' }))).toBe('Catamaran Light');
    expect(numberedFamily(names({ family: '3', typoFamily: 'Catamaran', typoSubfamily: 'Light Italic', subfamily: 'Italic' }))).toBe('Catamaran Light');
    expect(numberedFamily(names({ family: '4', typoFamily: 'Catamaran', typoSubfamily: 'Bold' }))).toBe('Catamaran');
    expect(numberedFamily(names({ family: '4', typoFamily: 'Catamaran' }))).toBe('Catamaran');
  });

  it('else the full name (nameID 4) without the number before it and the style (nameID 2) after it', () => {
    expect(numberedFamily(names({ family: '2', subfamily: 'Bold', full: '2Proxima Nova Bold', postscript: 'ProximaNova-Bold' }))).toBe('Proxima Nova');
    expect(numberedFamily(names({ family: '1', subfamily: 'Semibold', full: '1Proxima Nova Semibold', postscript: 'ProximaNova-Semibold' }))).toBe('Proxima Nova');
  });

  it("else the PostScript name (nameID 6): the table's family, or the name without its style, a weight kept as Windows names it", () => {
    expect(numberedFamily(names({ family: '2', subfamily: 'Bold', full: '2 Bold', postscript: 'Catamaran-Bold' }))).toBe('Catamaran');
    expect(numberedFamily(names({ family: '1', full: '1', postscript: 'Ledger-Regular' }))).toBe('Ledger');
    expect(numberedFamily(names({ family: '8', subfamily: 'Bold', full: '8 Bold', postscript: 'Geologica-Bold' }))).toBe('Geologica');
    expect(numberedFamily(names({ family: '1', full: '1 Regular', postscript: 'ShantiGreaterGoodVersion' }))).toBe('ShantiGreaterGoodVersion');
    expect(numberedFamily(names({ family: '5', full: '5', postscript: 'Catamaran-Light' }))).toBe('Catamaran Light');
    expect(numberedFamily(names({ family: '1', full: '1', postscript: 'MalgunGothicBold' }))).toBe('Malgun Gothic'); // the table's
  });

  it('else none: the number stays', () => {
    expect(numberedFamily(names({ family: '1', full: '1 Regular' }))).toBeNull();
    expect(numberedFamily(names({ family: '7', full: '7', postscript: '7' }))).toBeNull();
  });
});

describe('typefaceFamily: what lowering names a font', () => {
  const font = (baseFont: string, latinName: string | null, embedded = true) => ({ baseFont, latinName, embedded });

  it("an embedded font's own family stays, a known one or one the table does not know", () => {
    expect(typefaceFamily(font('ABCDEF+MalgunGothic', 'Malgun Gothic'))).toEqual({ family: 'Malgun Gothic', bold: false, italic: false });
    expect(typefaceFamily(font('ABCDEF+DeckbackSans-7Bold', 'Deckback Sans 7 Bold'))).toEqual({ family: 'Deckback Sans 7 Bold', bold: false, italic: false });
    expect(typefaceFamily(font('ABCDEF+DeckbackSans', 'DeckbackSans'))).toEqual({ family: 'DeckbackSans', bold: false, italic: false });
  });

  it("an embedded font whose family is a known family without its spaces gets the spaces, not the style", () => {
    expect(typefaceFamily(font('ABCDEF+MalgunGothicBold', 'MalgunGothic'))).toEqual({ family: 'Malgun Gothic', bold: false, italic: false });
  });

  it('a font without a program, or whose program has no names, takes its PostScript name, style included', () => {
    expect(typefaceFamily(font('MalgunGothic,Bold', 'MalgunGothic', false))).toEqual({ family: 'Malgun Gothic', bold: true, italic: false });
    expect(typefaceFamily(font('ABCDEF+Arial-BoldMT', null))).toEqual({ family: 'Arial', bold: true, italic: false });
    expect(typefaceFamily(font('FooBar,Bold', 'FooBar', false))).toEqual({ family: 'FooBar', bold: false, italic: false });
    expect(typefaceFamily(font('ABCDEF+FooBar-Bold', null))).toEqual({ family: 'FooBar', bold: false, italic: false });
    expect(typefaceFamily(font('', null))).toBeNull();
  });

  it('spacelessFamily: the known family a name is without its spaces, else null', () => {
    expect(spacelessFamily('MalgunGothic')).toBe('Malgun Gothic');
    expect(spacelessFamily('Malgun Gothic')).toBeNull();
    expect(spacelessFamily('NanumGothic')).toBeNull(); // a family of its own
    expect(spacelessFamily('DeckbackSans')).toBeNull();
  });
});
